$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
$zip=Get-ChildItem -LiteralPath (Join-Path $root 'outputs') -Filter 'ACTUALIZACION_V474_COMPLETA_PRIVADA_MONSTERASP_*.zip'|Sort-Object LastWriteTime -Descending|Select-Object -First 1
if(!$zip){throw 'No se encontró el paquete V474'}
Add-Type -AssemblyName System.IO.Compression.FileSystem
$archive=[IO.Compression.ZipFile]::OpenRead($zip.FullName)
function Read-Entry([string]$name){$entry=$archive.GetEntry($name);if(!$entry){throw "Falta $name"};$reader=[IO.StreamReader]::new($entry.Open());try{$reader.ReadToEnd()}finally{$reader.Dispose()}}
try{foreach($prefix in @('','wwwroot/')){$version=(Read-Entry ($prefix+'wwwroot/version-web.json'))|ConvertFrom-Json;if($version.release-ne'V474'-or$version.voiceOperations-ne'mobile-visible-questions-option-labels-v474'){throw 'Marcadores V474 incorrectos'};$config=Read-Entry ($prefix+'web.config');if($config-notmatch'RegistroAgencias.SqlServer.V474.exe'){throw 'Ejecutable incorrecto'};$xml=[xml]$config;$credential=$xml.SelectSingleNode("//environmentVariable[@name='STORAGE_KEY']");if(!$credential-or[string]::IsNullOrWhiteSpace($credential.GetAttribute('value'))){throw 'Falta almacenamiento privado'};$scripts=($archive.Entries|Where-Object {$_.FullName-like($prefix+'wwwroot/assets/*.js')}|ForEach-Object {Read-Entry $_.FullName})-join"`n";$styles=($archive.Entries|Where-Object {$_.FullName-like($prefix+'wwwroot/assets/*.css')}|ForEach-Object {Read-Entry $_.FullName})-join"`n";foreach($marker in @('Pregunta actual','Todas las fallas activas','Artículos del inventario')){if(!$scripts.Contains($marker)){throw "Falta marcador de interfaz: $marker"}};foreach($marker in @('.header-account .admin-voice-popover :is(span,strong,small)','visibility:visible!important','.admin-voice-question strong')){if(!$styles.Contains($marker)){throw "Falta protección visual: $marker"}};if(!$archive.GetEntry($prefix+'RegistroAgencias.SqlServer.V474.dll')-or!$archive.GetEntry($prefix+'RegistroAgencias.SqlServer.V474.exe')){throw 'Falta API V474'}};if($archive.Entries.FullName|Where-Object {$_-match'(^|/)(\.env[^/]*|appsettings[^/]*|app_offline\.htm)$|(^|/)(App_Data|uploads|logs|node_modules)/'}){throw 'Contenido no permitido'}}finally{$archive.Dispose()}
$hash=(Get-FileHash -LiteralPath $zip.FullName -Algorithm SHA256).Hash
Set-Content -LiteralPath ($zip.FullName+'.sha256.txt') -Value "$hash  $($zip.Name)" -Encoding ascii
[pscustomobject]@{Zip=$zip.FullName;MB=[Math]::Round($zip.Length/1MB,2);SHA256=$hash;QuestionText='visible';OptionNames='visible';MobileHeaderOverride='verified';Release='V474'}|ConvertTo-Json
